package br.com.onda;
import org.junit.Test;
import org.json.JSONException;
import java.util.*;
import static org.junit.Assert.*;
public class BackupDataTest {
 private BackupData.Archive sample(){BackupData.Archive a=new BackupData.Archive();a.tracks.add(new BackupData.Track("1","Canção","Artista","Álbum",60000));PlaylistStore.Entry list=new PlaylistStore.Entry("source","Viagem");list.songs.add("1");a.lists.add(list);a.favorites.add("1");a.phrases.put(null,"hora de viajar",VoiceCommand.Action.PLAY_PLAYLIST,"Viagem",0);return a;}
 @Test public void roundTripAndRemapToAnotherPhoneWithoutTrustingIds()throws Exception{BackupData.Archive a=BackupData.parse(BackupData.json(sample()));BackupData.Plan p=BackupData.merge(a,Arrays.asList(new BackupData.Track("1","Outra","Outro","",60000),new BackupData.Track("98","Cancao","Artista","Album",60500)),Collections.emptyList(),Collections.emptySet(),new VoicePhraseBook("[]"));assertEquals(Arrays.asList("98"),p.lists.get(0).songs);assertEquals(Set.of("98"),p.favorites);assertEquals(1,p.addedPhrases);assertEquals(1,p.matched);assertEquals("Viagem",p.phrases.find("hora de viajar").query);}
 @Test public void missingAndAmbiguousTracksNeverBecomeWrongFavorites(){BackupData.Archive a=sample();BackupData.Plan missing=BackupData.merge(a,Collections.emptyList(),Collections.emptyList(),Collections.emptySet(),new VoicePhraseBook("[]"));assertEquals(1,missing.missing);assertTrue(missing.favorites.isEmpty());BackupData.Track one=new BackupData.Track("4","Canção","Artista","Álbum",60000),two=new BackupData.Track("5","Canção","Artista","Álbum",60000);BackupData.Plan ambiguous=BackupData.merge(a,Arrays.asList(one,two),Collections.emptyList(),Collections.emptySet(),new VoicePhraseBook("[]"));assertEquals(1,ambiguous.ambiguous);assertTrue(ambiguous.lists.get(0).songs.isEmpty());}
 @Test public void mergingIsIdempotentAndPreservesExistingDataAndVoiceConflict(){BackupData.Archive a=sample();List<BackupData.Track> available=Arrays.asList(new BackupData.Track("9","Canção","Artista","Álbum",60000));PlaylistStore.Entry local=new PlaylistStore.Entry("local","viagem");local.songs.add("7");VoicePhraseBook phrases=new VoicePhraseBook("[]");phrases.put(null,"hora de viajar",VoiceCommand.Action.PAUSE,"",0);BackupData.Plan p=BackupData.merge(a,available,Arrays.asList(local),Set.of("7"),phrases);assertEquals(Arrays.asList("7","9"),p.lists.get(0).songs);assertEquals(VoiceCommand.Action.PAUSE,p.phrases.find("hora de viajar").action);assertEquals(1,p.conflicts);BackupData.Plan twice=BackupData.merge(a,available,p.lists,p.favorites,p.phrases);assertEquals(0,twice.addedLists+twice.addedSongs+twice.addedFavorites+twice.addedPhrases);assertEquals(Arrays.asList("7"),local.songs);}
 @Test public void rejectsUnknownVersionsAndDanglingReferences()throws Exception{String raw=BackupData.json(sample());try{BackupData.parse(raw.replace("\"version\": 1","\"version\": 2"));fail();}catch(JSONException expected){}try{BackupData.parse(raw.replace("\"key\": \"1\"","\"key\": \"2\""));fail();}catch(JSONException expected){}try{BackupData.parse("{}");fail();}catch(JSONException expected){}}
 @Test public void parseAddCommandAndAliases(){VoiceCommand c=VoiceCommand.parse("Onda, adicione esta música à minha playlist Viagem");assertEquals(VoiceCommand.Action.ADD_PLAYLIST,c.action);assertEquals("Viagem",c.query);assertEquals(VoiceCommand.Action.ADD_PLAYLIST,LocalVoiceModel.interpret("inclua essa faixa na lista Treino").action);assertEquals(VoiceCommand.Action.SEARCH,VoiceCommand.parse("pesquise adicione musica na lista treino").action);assertEquals("Treino",VoiceCommand.custom(VoiceCommand.Action.ADD_PLAYLIST,"Treino",0).query);}
 @Test public void preservesEmojiOnlyPlaylistNames()throws Exception{BackupData.Archive a=sample();a.lists.get(0).name="🎵";BackupData.Archive parsed=BackupData.parse(BackupData.json(a));PlaylistStore.Entry local=new PlaylistStore.Entry("local","🌙");BackupData.Plan p=BackupData.merge(parsed,Collections.emptyList(),Arrays.asList(local),Collections.emptySet(),new VoicePhraseBook("[]"));assertEquals(2,p.lists.size());assertEquals("🎵",p.lists.get(1).name);}
}
